'use client';
import React from 'react';

import EmojiPicker from 'emoji-picker-react';


// Tapback set: love, like, dislike, laugh, emphasize, question.
export type ShellProps = {
  /** The picker root: EmojiPicker, or a styled() wrapper of it. */
  Root?: React.ComponentType<React.ComponentProps<typeof EmojiPicker>>;
  className?: string;
};

export function Shell({ Root: RootComponent = EmojiPicker, className }: ShellProps) {
  return (
    <div className="imessage-stage">
      <RootComponent         className={className}
        colorScheme="dark"
        reactionsDefaultOpen
        reactions={['2764-fe0f', '1f44d', '1f44e', '1f602', '203c-fe0f', '2753']}
      />
      <div className="imessage-bubble">Dinner at 8? I booked the place by the river.</div>
    </div>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.imessage-stage {
  width: 420px;
  padding: 40px 24px 24px;
  border-radius: 24px;
  background: linear-gradient(160deg, #1c1c1e, #000);
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Helvetica Neue',
    Arial, sans-serif;
}
.imessage-bubble {
  max-width: 280px;
  margin: 10px 0 0 auto;
  padding: 9px 14px;
  border-radius: 20px;
  background: #0066d6;
  color: #fff;
  font-size: 16px;
  line-height: 1.35;
}

/* iMessage — tapback bar over a message bubble: dark translucent glass,
   large glyphs, the six classic tapbacks plus "+" for any emoji. */
/* Picker styles — the source of truth for every stack variant. */
.imessage-picker {
  --epr-reactions-bg-color: rgb(58 58 60 / 85%);
  --epr-bg-color: #1c1c1e;
  --epr-picker-border-color: transparent;
  --epr-hover-bg-color: rgb(255 255 255 / 12%);
  --epr-hover-bg-color-reduced-opacity: rgb(255 255 255 / 12%);
  --epr-text-color: #ebebf5;
  --epr-category-label-bg-color: rgb(28 28 30 / 94%);
  --epr-category-label-text-color: #ebebf5;
  --epr-search-input-bg-color: rgb(118 118 128 / 24%);
  --epr-search-input-bg-color-active: rgb(118 118 128 / 32%);
  --epr-search-input-text-color: #ebebf5;
  --epr-search-input-placeholder-color: rgb(235 235 245 / 60%);
  --epr-search-border-color: transparent;
  --epr-search-border-color-active: #0a84ff;
  --epr-emoji-size: 34px;
  margin-left: auto;
  box-shadow: 0 10px 30px rgb(0 0 0 / 50%);
}
.imessage-picker[data-epr-part='root'] {
  height: 56px;
}
.imessage-picker [data-epr-part='reactions'] {
  gap: 2px;
  padding: 0 8px;
}
.imessage-picker [data-epr-part='expand-reactions'] {
  background-color: rgb(255 255 255 / 14%);
  filter: invert(1) brightness(1.6);
}

/* Generated by scripts/generateRecipes.mts from picker.css — do not edit. */
